27	struct vmap_route_nav {
28	    vmap_route_t * route;
29	    vmap_route_nav_state_t state;
30	    uint32_t maneuver_hint;
31	    uint32_t track_seg_hint;
32	    double track_seg_start_m;
33	    bool track_hint_valid;
34	    uint32_t last_passed_maneuver;
35	    double off_route_threshold_m;
36	    double opposite_accum_m;
37	    double junction_off_accum_m;
38	    double prev_lon;
39	    double prev_lat;
40	    bool has_prev;
41	    bool need_reroute;
42	    vmap_route_reroute_reason_t reroute_reason;
43	    /** 上次提出重规划的时刻（ticks）与"抑制中"日志的限频时刻 —— 见
44	     *  VMAP_NAV_REROUTE_MIN_INTERVAL_MS：偏航判定在稀几何下会每帧成立。 */
45	    uint32_t last_reroute_tick;
46	    uint32_t reroute_suppress_log_tick;
47	};
48	/* 偏航重规划节流：允许就记录时刻并返回 true；否则按秒限频打日志并返回 false。 */
49	static bool nav_reroute_cooldown_ok(vmap_route_nav_t * nav)
50	{
51	    const uint32_t now = (uint32_t)clock_systime_ticks();
52	
53	    if (nav->last_reroute_tick != 0u
54	        && (uint32_t)(now - nav->last_reroute_tick)
55	            < (uint32_t)MSEC2TICK(VMAP_NAV_REROUTE_MIN_INTERVAL_MS)) {
56	        if (nav->reroute_suppress_log_tick == 0u
57	            || (uint32_t)(now - nav->reroute_suppress_log_tick)
58	                >= (uint32_t)MSEC2TICK(1000u)) {
59	            nav->reroute_suppress_log_tick = now;
60	            VMAP_NAV_WARN("off-route reroute suppressed (<%u ms since last)",
61	                (unsigned)VMAP_NAV_REROUTE_MIN_INTERVAL_MS);
62	        }
63	        return false;
64	    }
65	
66	    nav->last_reroute_tick = now;
67	    return true;
68	}
