95	static void nav_update_passed_maneuvers(vmap_route_nav_t * nav, double along_m)
96	{
97	    const vmap_route_maneuver_t * mans;
98	    uint32_t n;
99	    uint32_t passed = UINT32_MAX;
100	
101	    if (!nav || !nav->route) {
102	        return;
103	    }
104	
105	    mans = vmap_route_maneuvers(nav->route);
106	    n = vmap_route_maneuver_count(nav->route);
107	    if (!mans || n == 0) {
108	        return;
109	    }
110	
111	    for (uint32_t i = 0; i < n; i++) {
112	        const vmap_maneuver_kind_t kind = mans[i].kind;
113	
114	        if (kind == VMAP_MANEUVER_START || kind == VMAP_MANEUVER_ARRIVE) {
115	            continue;
116	        }
117	        if (along_m >= mans[i].along_m + 15.0) {
118	            passed = i;
119	        }
120	    }
121	    nav->last_passed_maneuver = passed;
122	}
