124	static bool nav_passed_junction(const vmap_route_nav_t * nav)
125	{
126	    const vmap_route_maneuver_t * mans;
127	
128	    if (!nav || nav->last_passed_maneuver == UINT32_MAX || !nav->route) {
129	        return false;
130	    }
131	
132	    mans = vmap_route_maneuvers(nav->route);
133	    if (!mans) {
134	        return false;
135	    }
136	    return mans[nav->last_passed_maneuver].kind != VMAP_MANEUVER_START;
137	}
