139	/** @brief 过路口后：nav_off_route_m 处 90°，至 2 倍处线性降至 0°。 */
140	static float nav_junction_angle_limit_deg(double off_m, double threshold)
141	{
142	    const double t1 = threshold;
143	    const double t2 = threshold * 2.0;
144	
145	    if (off_m >= t2) {
146	        return 0.0f;
147	    }
148	    if (off_m <= t1) {
149	        return 90.0f;
150	    }
151	    return 90.0f * (float)((t2 - off_m) / (t2 - t1));
152	}
