154	static void nav_update_next_maneuver(vmap_route_nav_t * nav, double along_m,
155	    double remain_m)
156	{
157	    const vmap_route_maneuver_t * mans;
158	    uint32_t n;
159	    uint32_t idx;
160	
161	    nav->state.maneuver_idx = UINT32_MAX;
162	    nav->state.next_kind = VMAP_MANEUVER_NONE;
163	    nav->state.dist_to_maneuver_m = 0.0;
164	    nav->state.turn_rel_deg = 0.0f;
165	    nav->state.next_road = NULL;
166	
167	    if (!nav || !nav->route) {
168	        return;
169	    }
170	
171	    mans = vmap_route_maneuvers(nav->route);
172	    n = vmap_route_maneuver_count(nav->route);
173	    if (!mans || n == 0) {
174	        return;
175	    }
176	
177	    idx = nav->maneuver_hint;
178	    while (idx < n && mans[idx].along_m < along_m - 20.0) {
179	        idx++;
180	    }
181	    nav->maneuver_hint = idx;
182	
183	    for (; idx < n; idx++) {
184	        const vmap_maneuver_kind_t kind = mans[idx].kind;
185	        double dist;
186	
187	        if (kind == VMAP_MANEUVER_START) {
188	            continue;
189	        }
190	
191	        if (kind == VMAP_MANEUVER_ARRIVE) {
192	            if (remain_m <= VMAP_ROUTE_ARRIVE_M) {
193	                nav->state.maneuver_idx = idx;
194	                nav->state.next_kind = kind;
195	                nav->state.dist_to_maneuver_m = remain_m;
196	            }
197	            return;
198	        }
199	
200	        dist = mans[idx].along_m - along_m;
201	        if (dist < -15.0) {
202	            continue;
203	        }
204	
205	        nav->state.maneuver_idx = idx;
206	        nav->state.next_kind = kind;
207	        nav->state.dist_to_maneuver_m = dist > 0.0 ? dist : 0.0;
208	        nav->state.turn_rel_deg = mans[idx].turn_deg;
209	        nav->state.next_road = mans[idx].road_name;
210	        return;
211	    }
212	}
