214	static void nav_update_deviation(vmap_route_nav_t * nav, double lon, double lat,
215	    float course_deg, float speed_kph, double off_m, uint32_t seg)
216	{
217	    const vmap_route_pt_t * pts;
218	    uint32_t n;
219	    double step_m = 0.0;
220	    float move_brg = course_deg;
221	    float route_brg;
222	    float delta;
223	    const double threshold = nav->off_route_threshold_m > 0.0
224	        ? nav->off_route_threshold_m : 50.0;
225	
226	    if (!nav || !nav->route) {
227	        return;
228	    }
229	
230	    pts = vmap_route_points(nav->route);
231	    n = vmap_route_point_count(nav->route);
232	    if (!pts || seg + 1u >= n) {
233	        return;
234	    }
235	
236	    route_brg = vmap_geo_bearing_deg(pts[seg].lon, pts[seg].lat,
237	        pts[seg + 1u].lon, pts[seg + 1u].lat);
238	
239	    if (nav->has_prev) {
240	        step_m = vmap_geo_haversine_m(nav->prev_lon, nav->prev_lat, lon, lat);
241	        if (step_m >= 3.0) {
242	            move_brg = vmap_geo_bearing_deg(nav->prev_lon, nav->prev_lat, lon, lat);
243	        }
244	    }
245	
246	    delta = vmap_geo_angle_delta_deg(route_brg, move_brg);
247	
248	    if (nav_passed_junction(nav) && off_m >= threshold * 2.0
249	        && nav_reroute_cooldown_ok(nav)) {
250	        nav->need_reroute = true;
251	        nav->reroute_reason = VMAP_ROUTE_REROUTE_JUNCTION_FAR;
252	        VMAP_NAV_WARN("off-route reroute: junction off=%.0fm >= 2x threshold %.0fm",
253	            off_m, threshold);
254	    } else if (speed_kph >= 3.0f && step_m >= 1.0) {
255	        /* 逆行只在**贴着路线**时才有意义：off_m 已经很大时，`delta` 比的是骑行者
256	         * 与"最近那条路线段"的方位 —— 那条段属于**另一条路**，夹角毫无意义。
257	         * 实测现场：骑行者离路线 289 m、正沿 金陵路 朝终点骑，却一路被判"逆行"。
258	         * 偏航（不在路线上）交给下面的 junction-far / accum 规则处理。 */
259	        if (fabsf(delta) > 90.0f && off_m <= threshold) {
260	            nav->opposite_accum_m += step_m;
261	        } else {
262	            nav->opposite_accum_m = 0.0;
263	        }
264	
265	        if (nav_passed_junction(nav) && off_m > VMAP_ROUTE_OFF_M) {
266	            const float angle_limit = nav_junction_angle_limit_deg(off_m, threshold);
267	
268	            if (fabsf(delta) > angle_limit) {
269	                nav->junction_off_accum_m += step_m;
270	            }
271	        } else if (off_m <= VMAP_ROUTE_OFF_M * 0.5) {
272	            nav->junction_off_accum_m = 0.0;
273	        }
274	    }
275	
276	    nav->prev_lon = lon;
277	    nav->prev_lat = lat;
278	    nav->has_prev = true;
279	
280	    if (!nav->need_reroute
281	        && (nav->opposite_accum_m >= threshold
282	            || nav->junction_off_accum_m >= threshold)
283	        && nav_reroute_cooldown_ok(nav)) {
284	        nav->need_reroute = true;
285	        if (nav->opposite_accum_m >= threshold) {
286	            nav->reroute_reason = VMAP_ROUTE_REROUTE_OPPOSITE;
287	        } else {
288	            nav->reroute_reason = VMAP_ROUTE_REROUTE_JUNCTION_ACCUM;
289	        }
290	        VMAP_NAV_WARN("off-route reroute opposite=%.0fm junction=%.0fm off=%.0fm "
291	            "angle=%.0f limit=%.0f reason=%d",
292	            nav->opposite_accum_m, nav->junction_off_accum_m, off_m,
293	            (double)fabsf(delta),
294	            (double)nav_junction_angle_limit_deg(off_m, threshold),
295	            (int)nav->reroute_reason);
296	    }
297	}
