337	/**
338	 * @brief vmap route nav plan to。
339	 */
340	bool vmap_route_nav_plan_to(vmap_route_nav_t * nav,
341	    double from_lon, double from_lat, double to_lon, double to_lat)
342	{
343	    if (!nav || !nav->route) {
344	        return false;
345	    }
346	    memset(&nav->state, 0, sizeof(nav->state));
347	    nav->maneuver_hint = 0;
348	    nav_reset_track_match(nav);
349	    nav_reset_deviation(nav);
350	    if (!vmap_route_plan(nav->route, from_lon, from_lat, to_lon, to_lat)) {
351	        return false;
352	    }
353	    nav->state.active = true;
354	    nav->state.remain_m = vmap_route_total_length_m(nav->route);
355	    nav->state.maneuver_idx = UINT32_MAX;
356	    return true;
357	}
