415	/**
416	 * @brief vmap route nav take reroute。
417	 */
418	vmap_route_reroute_reason_t vmap_route_nav_take_reroute(vmap_route_nav_t * nav)
419	{
420	    vmap_route_reroute_reason_t reason;
421	
422	    if (!nav || !nav->need_reroute) {
423	        return VMAP_ROUTE_REROUTE_NONE;
424	    }
425	    reason = nav->reroute_reason;
426	    if (reason == VMAP_ROUTE_REROUTE_NONE) {
427	        reason = VMAP_ROUTE_REROUTE_JUNCTION_ACCUM;
428	    }
429	    nav->need_reroute = false;
430	    nav->reroute_reason = VMAP_ROUTE_REROUTE_NONE;
431	    return reason;
432	}
