451	/**
452	 * @brief vmap route nav update。
453	 */
454	void vmap_route_nav_update(vmap_route_nav_t * nav, double lon, double lat,
455	    float course_deg, float speed_kph)
456	{
457	    const vmap_route_pt_t * pts;
458	    uint32_t n;
459	    uint32_t seg = 0;
460	    double off_m;
461	    double along;
462	    double total;
463	
464	    if (!nav || !vmap_route_is_active(nav->route)) {
465	        return;
466	    }
467	
468	    pts = vmap_route_points(nav->route);
469	    n = vmap_route_point_count(nav->route);
470	    if (n < 2) {
471	        return;
472	    }
473	
474	    {
475	        double best_d = 1e18;
476	        double best_score = 1e18;
477	        double best_along = 0.0;
478	        double best_seg_start_m = 0.0;
479	        double best_t = 0.0;
480	        const bool continuity = nav->track_hint_valid && nav->state.active;
481	        const double prev_along = nav->state.along_m;
482	        double acc;
483	        uint32_t hint;
484	        uint32_t start;
485	        uint32_t end;
486	        bool acquire_all;
487	
488	        acquire_all = !nav->track_hint_valid;
489	        hint = nav->track_seg_hint;
490	        if (!acquire_all && hint + 1u >= n) {
491	            hint = n - 2u;
492	        }
493	
494	        if (acquire_all) {
495	            uint32_t stride = 1u;
496	            uint32_t coarse = 0;
497	            double coarse_d = 1e18;
498	            double coarse_acc = 0.0;
499	            double run = 0.0;
500	            const uint32_t last_seg = n - 2u;
501	
502	            if (last_seg + 1u > VMAP_NAV_MATCH_ACQUIRE_MAX) {
503	                stride = (last_seg + VMAP_NAV_MATCH_ACQUIRE_MAX)
504	                    / VMAP_NAV_MATCH_ACQUIRE_MAX;
505	            }
506	            for (uint32_t i = 0; i <= last_seg; i++) {
507	                if ((i % stride) == 0u || i == last_seg) {
508	                    double tloc = 0.0;
509	                    const double d = vmap_geo_point_to_seg_m(lon, lat,
510	                        pts[i].lon, pts[i].lat, pts[i + 1].lon, pts[i + 1].lat,
511	                        &tloc);
512	
513	                    if (d < coarse_d) {
514	                        coarse_d = d;
515	                        coarse = i;
516	                        coarse_acc = run;
517	                    }
518	                }
519	                run += vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
520	                    pts[i + 1].lon, pts[i + 1].lat);
521	            }
522	            hint = coarse;
523	            start = hint > VMAP_NAV_MATCH_ACQUIRE_HALF
524	                ? hint - VMAP_NAV_MATCH_ACQUIRE_HALF : 0u;
525	            end = hint + VMAP_NAV_MATCH_ACQUIRE_HALF;
526	            if (end > last_seg) {
527	                end = last_seg;
528	            }
529	            acc = coarse_acc;
530	        } else {
531	            start = hint > VMAP_NAV_MATCH_BACK_SEGS
532	                ? hint - VMAP_NAV_MATCH_BACK_SEGS : 0u;
533	            end = hint + VMAP_NAV_MATCH_AHEAD_SEGS;
534	            if (end + 1u >= n) {
535	                end = n - 2u;
536	            }
537	            acc = nav->track_seg_start_m;
538	        }
539	
540	        for (uint32_t i = hint; i > start; i--) {
541	            acc -= vmap_geo_haversine_m(pts[i - 1u].lon, pts[i - 1u].lat,
542	                pts[i].lon, pts[i].lat);
543	        }
544	
545	        for (uint32_t i = start; i <= end; i++) {
546	            double tloc = 0.0;
547	            const double d = vmap_geo_point_to_seg_m(lon, lat,
548	                pts[i].lon, pts[i].lat, pts[i + 1].lon, pts[i + 1].lat, &tloc);
549	            const double seg_m = vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
550	                pts[i + 1].lon, pts[i + 1].lat);
551	            const double candidate_along = acc + seg_m * tloc;
552	            double score = d;
553	
554	            if (continuity) {
555	                const double delta = candidate_along - prev_along;
556	                double excess = 0.0;
557	
558	                if (delta < -VMAP_NAV_MATCH_BACK_TOL_M) {
559	                    excess = -delta - VMAP_NAV_MATCH_BACK_TOL_M;
560	                } else if (delta > VMAP_NAV_MATCH_AHEAD_TOL_M) {
561	                    excess = delta - VMAP_NAV_MATCH_AHEAD_TOL_M;
562	                }
563	                score += fmin(VMAP_NAV_MATCH_MAX_PENALTY,
564	                    excess * VMAP_NAV_MATCH_PROGRESS_W);
565	            }
566	
567	            if (score < best_score) {
568	                best_score = score;
569	                best_d = d;
570	                seg = i;
571	                best_seg_start_m = acc;
572	                best_t = tloc;
573	                best_along = candidate_along;
574	            }
575	            acc += seg_m;
576	        }
577	
578	        nav->track_seg_hint = seg;
579	        nav->track_seg_start_m = best_seg_start_m;
580	        nav->track_hint_valid = true;
