13	double vmap_geo_haversine_m(double lon1, double lat1, double lon2, double lat2)
14	{
15	    const double r = 6371000.0;
16	    const double dlat = (lat2 - lat1) * M_PI / 180.0;
17	    const double dlon = (lon2 - lon1) * M_PI / 180.0;
18	    const double lat1r = lat1 * M_PI / 180.0;
19	    const double lat2r = lat2 * M_PI / 180.0;
20	    const double a = sin(dlat / 2.0) * sin(dlat / 2.0)
21	        + cos(lat1r) * cos(lat2r) * sin(dlon / 2.0) * sin(dlon / 2.0);
22	
23	    return 2.0 * r * asin(fmin(1.0, sqrt(a)));
24	}
