26	/**
27	 * @brief vmap geo bearing deg。
28	 */
29	float vmap_geo_bearing_deg(double lon1, double lat1, double lon2, double lat2)
30	{
31	    const double lat1r = lat1 * M_PI / 180.0;
32	    const double lat2r = lat2 * M_PI / 180.0;
33	    const double dlon = (lon2 - lon1) * M_PI / 180.0;
34	    const double y = sin(dlon) * cos(lat2r);
35	    const double x = cos(lat1r) * sin(lat2r)
36	        - sin(lat1r) * cos(lat2r) * cos(dlon);
37	    float brg = (float)(atan2(y, x) * 180.0 / M_PI);
38	
39	    if (brg < 0.0f) {
40	        brg += 360.0f;
41	    }
42	    return brg;
43	}
