85	 *
86	 * @note 用局部等距圆柱平面算距离与投影参数。纬向用 `110540 m/°`，比球面模型
87	 *       （R=6371 km ⇒ 111195 m/°）低约 0.59%。**已测样本**：22~45°N 的单段距离
88	 *       误差 0.59~0.62%；高纬会更大（79°N、段长 400 m 时 0.91%）⇒ 没有全域上界，
89	 *       但在产品纬度带可以按 0.7% 估。这是刻意的扁率近似，不是 bug。
90	 *       **不要再改回 haversine + bearing**：那是逐段 FP64 三角函数的开销，
91	 *       见上面 cos 近似的说明。
92	 */
93	double vmap_geo_point_to_seg_m(double px, double py,
94	    double ax, double ay, double bx, double by, double * t_out)
95	{
96	    const double kx = 111320.0 * vmap_geo_cos_deg(ay);
97	    const double vx = (bx - ax) * kx;
98	    const double vy = (by - ay) * VMAP_GEO_M_PER_DEG_LAT;
99	    const double wx = (px - ax) * kx;
100	    const double wy = (py - ay) * VMAP_GEO_M_PER_DEG_LAT;
101	    const double seg2 = vx * vx + vy * vy;
102	    double t = 0.0;
103	
104	    if (seg2 > 1e-6) {
105	        t = (wx * vx + wy * vy) / seg2;
106	        if (t < 0.0) {
107	            t = 0.0;
108	        } else if (t > 1.0) {
109	            t = 1.0;
110	        }
111	    }
112	
113	    if (t_out) {
114	        *t_out = t;
115	    }
116	
117	    {
118	        const double dx = wx - vx * t;
119	        const double dy = wy - vy * t;
120	
121	        return sqrt(dx * dx + dy * dy);
122	    }
123	}
