static double geo_cos_deg(double deg)
{
    const double x = deg * (M_PI / 180.0);
    const double x2 = x * x;

    return 1.0 - x2 * 0.5 + x2 * x2 * (1.0 / 24.0)
        - x2 * x2 * x2 * (1.0 / 720.0)
