    const double vx = (bx - ax) * kx;
    const double vy = (by - ay) * GEO_M_PER_DEG_LAT;
    const double wx = (px - ax) * kx;
    const double wy = (py - ay) * GEO_M_PER_DEG_LAT;
    const double seg2 = vx * vx + vy * vy;
    double t = 0.0;

    if (seg2 > 1e-6) {
        t = (wx * vx + wy * vy) / seg2;
        if (t < 0.0) {
            t = 0.0;
        } else if (t > 1.0) {
            t = 1.0;
        }
    }

    if (t_out) {
        *t_out = t;
